  <script type="module">
    function renderCharCard(charKey, data) {
      const char = data[charKey];
      if (!char) return;

      const card = $(`#card-${charKey.replace(/[^a-zA-Z\u4e00-\u9fa5]/g, '')}`);
      if (!card.length) return;

      /* 好感度 */
      const aff = char.好感度 || 0;
      const affBar = card.find('.bar-affection');
      affBar.css('width', aff + '%');
      if (aff > 0) {
        affBar.addClass('has-value');
      } else {
        affBar.removeClass('has-value');
      }
      card.find('.val-affection').text(aff);

      /* 淫乱值 */
      const lewd = char.淫乱值 || 0;
      const lewdBar = card.find('.bar-lewd');
      lewdBar.css('width', lewd + '%');
      if (lewd > 0) {
        lewdBar.addClass('has-value');
      } else {
        lewdBar.removeClass('has-value');
      }
      card.find('.val-lewd').text(lewd);

      /* 怀孕 */
      const preg = char.是否怀孕 || '否';
      const pregTag = card.find('.preg-tag');
      pregTag.text(preg === '是' ? '妊娠中' : '未怀孕');
      pregTag.removeClass('preg-yes preg-no');
      pregTag.addClass(preg === '是' ? 'preg-yes' : 'preg-no');

      /* 器官 */
      const organs = char.器官 || {};
      ['乳房', '阴道', '肛门', '口腔'].forEach(organ => {
        const o = organs[organ] || {};
        const dev = o.开发度 || '';
        const count = o.使用次数 || 0;
        card.find(`.dev-${organ}`).text(dev || '-');
        card.find(`.count-${organ}`).text(count);
      });

      /* 认证雄性 */
      const males = char.认证雄性 || {};
      const malePanel = card.find('.panel-males');
      malePanel.empty();
      const maleKeys = Object.keys(males);
      if (maleKeys.length === 0) {
        malePanel.html('<div class="empty-hint">暂无认证雄性</div>');
      } else {
        maleKeys.forEach(name => {
          const m = males[name];
          const level = m.精液中毒程度 || '未中毒';
          const pref = m.偏好 || '';
          malePanel.append(`
            <div class="male-entry">
              <span class="male-name">${name}</span>
              <span class="addict-tag addict-${level}">${level}</span>
              ${pref ? `<div class="male-detail">偏好：${pref}</div>` : ''}
            </div>
          `);
        });
      }

      /* 称号 */
      const titles = char.称号 || {};
      const titlePanel = card.find('.panel-titles');
      titlePanel.empty();
      const titleKeys = Object.keys(titles);
      if (titleKeys.length === 0) {
        titlePanel.html('<div class="empty-hint">暂无称号</div>');
      } else {
        titleKeys.forEach(name => {
          const t = titles[name];
          titlePanel.append(`
            <div class="title-entry">
              <span class="title-name">「${name}」</span>
              <span class="title-desc">${t.注释 || ''}</span>
              ${t.调侃 ? `<div class="title-joke">${t.调侃}</div>` : ''}
            </div>
          `);
        });
      }
    }

    function populateAllData() {
      const all_variables = getAllVariables();
      const data = _.get(all_variables, 'stat_data', {});

      const chars = ['琉歌', '恩雅·初雪', '施比拉', '伊庇娅'];
      chars.forEach(charKey => {
        renderCharCard(charKey, data);
      });
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateAllData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateAllData();
      });

      /* 折叠按钮 */
      $('.collapse-btn').on('click', function() {
        const target = $(this).data('target');
        const panel = $('#' + target);
        panel.toggleClass('show');
        $(this).toggleClass('open');
      });
    }

    $(errorCatched(init));
  </script>
