import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  琉歌: z.object({
    好感度: z.coerce.number().prefault(0).transform(v => _.clamp(v, 0, 100)),
    淫乱值: z.coerce.number().prefault(0).transform(v => _.clamp(v, 0, 100)),
    是否怀孕: z.enum(['是', '否']).prefault('否'),
    器官: z.object({
      乳房: z.object({
        开发度: z.string().prefault(''),
        使用次数: z.coerce.number().prefault(0),
      }),
      阴道: z.object({
        开发度: z.string().prefault(''),
        使用次数: z.coerce.number().prefault(0),
      }),
      肛门: z.object({
        开发度: z.string().prefault(''),
        使用次数: z.coerce.number().prefault(0),
      }),
      口腔: z.object({
        开发度: z.string().prefault(''),
        使用次数: z.coerce.number().prefault(0),
      }),
    }).prefault({
      乳房: { 开发度: '', 使用次数: 0 },
      阴道: { 开发度: '', 使用次数: 0 },
      肛门: { 开发度: '', 使用次数: 0 },
      口腔: { 开发度: '', 使用次数: 0 },
    }),
    认证雄性: z.record(
      z.string().describe('认证雄性名称'),
      z.object({
        精液中毒程度: z.enum(['未中毒', '轻度中毒', '中度中毒', '重度中毒', '上瘾']).prefault('未中毒'),
        偏好: z.string().prefault(''),
      }),
    ).prefault({}),
    称号: z.record(
      z.string().describe('称号名'),
      z.object({
        注释: z.string().prefault(''),
        调侃: z.string().prefault(''),
      }),
    ).prefault({}),
  }).prefault({
    好感度: 0,
    淫乱值: 0,
    是否怀孕: '否',
    器官: {
      乳房: { 开发度: '', 使用次数: 0 },
      阴道: { 开发度: '', 使用次数: 0 },
